package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// UserService provides business logic for users
type UserService struct {
	users  map[string]User
	mutex  sync.RWMutex
}

// NewUserService creates a new UserService
func NewUserService() *UserService {
	return &UserService{
		users: make(map[string]User),
	}
}

// GetAllUsers returns all users
func (s *UserService) GetAllUsers() []User {
	s.mutex.RLock()
	defer s.mutex.RUnlock()

	var list []User
	for _, u := range s.users {
		list = append(list, u)
	}
	return list
}

// CreateUser creates a new user and returns it
func (s *UserService) CreateUser(name, email string) (*User, error) {
	s.mutex.Lock()
	defer s.mutex.Unlock()

	id, err := uuid.NewRandom()
	if err != nil {
		return nil, fmt.Errorf("failed to generate UUID: %w", err)
	}

	u := User{
		ID:    id.String(),
		Name:  name,
		Email: email,
	}
	s.users[u.ID] = u
	return &u, nil
}

// GetUserByID returns a user by ID
func (s *UserService) GetUserByID(id string) (*User, error) {
	s.mutex.RLock()
	defer s.mutex.RUnlock()

	u, ok := s.users[id]
	if !ok {
		return nil, fmt.Errorf("user with ID %s not found", id)
	}
	return &u, nil
}

package api

import (
	"encoding/json"
	"fmt"
	"net/http"

	"legacy_refactor/rep-2/internal/service"
)

// Handlers holds the dependencies for API handlers
type Handlers struct {
	UserService *service.UserService
}

// NewHandlers creates new API handlers
func NewHandlers(us *service.UserService) *Handlers {
	return &Handlers{
		UserService: us,
	}
}

// HandleUsers handles requests for /users
func (h *Handlers) HandleUsers(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		h.GetUsers(w, r)
	case http.MethodPost:
		h.CreateUser(w, r)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// GetUsers returns all users
func (h *Handlers) GetUsers(w http.ResponseWriter, r *http.Request) {
	users := h.UserService.GetAllUsers()
	json.NewEncoder(w).Encode(users)
}

// CreateUser creates a new user
func (h *Handlers) CreateUser(w http.ResponseWriter, r *http.Request) {
	var u service.User
	if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	createdUser, err := h.UserService.CreateUser(u.Name, u.Email)
	if err != nil {
		http.Error(w, fmt.Sprintf("failed to create user: %v", err), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(createdUser)
}

// HandleUserByID handles requests for /users/{id}
func (h *Handlers) HandleUserByID(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/users/"):]
	switch r.Method {
	case http.MethodGet:
		h.GetUserByID(w, r, id)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// GetUserByID returns a user by ID
func (h *Handlers) GetUserByID(w http.ResponseWriter, r *http.Request, id string) {
	u, err := h.UserService.GetUserByID(id)
	if err != nil {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(u)
}

package main

import (
	"log"
	"net/http"
	"legacy_refactor/rep-2/internal/api"
	"legacy_refactor/rep-2/internal/service"
)

func main() {
	// Initialize service layer
	userService := service.NewUserService()

	// Initialize API handlers with the service
	apiHandlers := api.NewHandlers(userService)

	// Register HTTP routes
	http.HandleFunc("/users", apiHandlers.HandleUsers)
	http.HandleFunc("/users/", apiHandlers.HandleUserByID)

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"testing"

	"legacy_refactor/rep-2/internal/api"
	"legacy_refactor/rep-2/internal/service"
)

func TestUserAPI(t *testing.T) {
	// Initialize service and handlers
	userService := service.NewUserService()
	apiHandlers := api.NewHandlers(userService)

	// Setup HTTP server for testing
	mux := http.NewServeMux()
	mux.HandleFunc("/users", apiHandlers.HandleUsers)
	mux.HandleFunc("/users/", apiHandlers.HandleUserByID)

	// Test Create User (POST /users)
	user := service.User{Name: "John Doe", Email: "john@example.com"}
	body, _ := json.Marshal(user)
	req := httptest.NewRequest(http.MethodPost, "/users", bytes.NewReader(body))
	rw := httptest.NewRecorder()
	mux.ServeHTTP(rw, req)

	if rw.Code != http.StatusCreated {
		t.Errorf("Expected status %d, got %d", http.StatusCreated, rw.Code)
	}

	var createdUser service.User
	json.NewDecoder(rw.Body).Decode(&createdUser)
	if createdUser.ID == "" {
		t.Error("Expected user ID to be set, got empty")
	}

	// Test Get All Users (GET /users)
	req = httptest.NewRequest(http.MethodGet, "/users", nil)
	rw = httptest.NewRecorder()
	mux.ServeHTTP(rw, req)

	if rw.Code != http.StatusOK {
		t.Errorf("Expected status %d, got %d", http.StatusOK, rw.Code)
	}

	var users []service.User
	json.NewDecoder(rw.Body).Decode(&users)
	if len(users) != 1 {
		t.Errorf("Expected 1 user, got %d", len(users))
	}
	if users[0].ID != createdUser.ID {
		t.Errorf("Expected user ID %s, got %s", createdUser.ID, users[0].ID)
	}

	// Test Get User By ID (GET /users/{id})
	req = httptest.NewRequest(http.MethodGet, fmt.Sprintf("/users/%s", createdUser.ID), nil)
	rw = httptest.NewRecorder()
	mux.ServeHTTP(rw, req)

	if rw.Code != http.StatusOK {
		t.Errorf("Expected status %d, got %d", http.StatusOK, rw.Code)
	}

	var fetchedUser service.User
	json.NewDecoder(rw.Body).Decode(&fetchedUser)
	if fetchedUser.ID != createdUser.ID {
		t.Errorf("Expected user ID %s, got %s", createdUser.ID, fetchedUser.ID)
	}

	// Test Get Non-Existent User By ID (GET /users/{id})
	req = httptest.NewRequest(http.MethodGet, "/users/non-existent-id", nil)
	rw = httptest.NewRecorder()
	mux.ServeHTTP(rw, req)

	if rw.Code != http.StatusNotFound {
		t.Errorf("Expected status %d, got %d for non-existent user", http.StatusNotFound, rw.Code)
	}
}
